import React, { useState, useEffect } from "react";
import {
  FaUserEdit,
  FaLock,
  FaUser,
  FaEnvelope,
  FaTransgender,
  FaBirthdayCake,
} from "react-icons/fa";
import axiosClient from "../../utils/axiosConfig";

const PersonalInfo = () => {
  const [userInfo, setUserInfo] = useState({
    fullName: "",
    email: "",
    gender: "",
    birthDay: "",
    birthMonth: "",
    birthYear: "",
  });

  const [originalUserInfo, setOriginalUserInfo] = useState({});
  const [isEditing, setIsEditing] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const [password, setPassword] = useState({
    current: "",
    new: "",
    confirm: "",
  });

  // 1. Tải thông tin người dùng
  const fetchUserInfo = async () => {
    setIsLoading(true);
    try {
      const res = await axiosClient.get("/user/me");
      const data = res.data;
      setUserInfo(data);
      setOriginalUserInfo(data);
    } catch (error) {
      console.error("Lỗi tải thông tin:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchUserInfo();
  }, []);

  // 2. Lưu thông tin
  const handleSaveInfo = async () => {
    setIsLoading(true);
    try {
      const payload = {
        fullName: userInfo.fullName,
        gender: userInfo.gender,
        birthDay: userInfo.birthDay,
        birthMonth: userInfo.birthMonth,
        birthYear: userInfo.birthYear,
      };

      await axiosClient.put("/user/me", payload);
      setOriginalUserInfo(userInfo);
      setIsEditing(false);
      alert("Cập nhật thông tin thành công!");
    } catch (error) {
      alert(error.response?.data?.message || "Cập nhật thất bại.");
    } finally {
      setIsLoading(false);
    }
  };

  const inputGroupStyle = { marginBottom: "15px" };
  const labelStyle = {
    display: "flex",
    alignItems: "center",
    gap: "8px",
    marginBottom: "8px",
    fontWeight: "bold",
    fontSize: "0.9em",
    color: "#555",
  };
  const inputStyle = (editable) => ({
    padding: "10px",
    border: "1px solid #ddd",
    borderRadius: "4px",
    width: "100%",
    backgroundColor: editable ? "#fff" : "#f9f9f9",
    color: editable ? "#333" : "#777",
    outline: "none",
    fontSize: "1em",
  });

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "30px" }}>
      {/* KHỐI THÔNG TIN CÁ NHÂN */}
      <div
        style={{
          border: "1px solid #eee",
          padding: "25px",
          borderRadius: "10px",
          backgroundColor: "#fff",
          boxShadow: "0 2px 4px rgba(0,0,0,0.02)",
        }}
      >
        <h4
          style={{
            display: "flex",
            alignItems: "center",
            gap: "10px",
            color: "#c90000",
            marginBottom: "25px",
            borderBottom: "1px solid #eee",
            paddingBottom: "10px",
          }}
        >
          <FaUserEdit /> Thông tin tài khoản
        </h4>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gap: "25px",
          }}
        >
          {/* Họ và Tên */}
          <div style={inputGroupStyle}>
            <label style={labelStyle}>
              <FaUser color="#c90000" /> Họ và Tên
            </label>
            <input
              style={inputStyle(isEditing)}
              value={userInfo.fullName || ""}
              disabled={!isEditing}
              onChange={(e) =>
                setUserInfo({ ...userInfo, fullName: e.target.value })
              }
              placeholder="Nhập họ và tên"
            />
          </div>

          {/* Email (Disabled hoàn toàn) */}
          <div style={inputGroupStyle}>
            <label style={labelStyle}>
              <FaEnvelope color="#c90000" /> Email
            </label>
            <input
              style={inputStyle(false)}
              value={userInfo.email || ""}
              disabled
            />
          </div>

          {/* Giới tính - Sử dụng Select để tránh nhập sai */}
          <div style={inputGroupStyle}>
            <label style={labelStyle}>
              <FaTransgender color="#c90000" /> Giới tính
            </label>
            <select
              style={inputStyle(isEditing)}
              value={userInfo.gender || ""}
              disabled={!isEditing}
              onChange={(e) =>
                setUserInfo({ ...userInfo, gender: e.target.value })
              }
            >
              <option value="">Chọn giới tính</option>
              <option value="Nam">Nam</option>
              <option value="Nữ">Nữ</option>
              <option value="Khác">Khác</option>
            </select>
          </div>

          {/* Ngày sinh */}
          <div style={inputGroupStyle}>
            <label style={labelStyle}>
              <FaBirthdayCake color="#c90000" /> Ngày sinh (Ngày / Tháng / Năm)
            </label>
            <div style={{ display: "flex", gap: "10px" }}>
              <input
                placeholder="Ngày"
                style={{ ...inputStyle(isEditing), textAlign: "center" }}
                value={userInfo.birthDay || ""}
                disabled={!isEditing}
                onChange={(e) =>
                  setUserInfo({ ...userInfo, birthDay: e.target.value })
                }
              />
              <input
                placeholder="Tháng"
                style={{ ...inputStyle(isEditing), textAlign: "center" }}
                value={userInfo.birthMonth || ""}
                disabled={!isEditing}
                onChange={(e) =>
                  setUserInfo({ ...userInfo, birthMonth: e.target.value })
                }
              />
              <input
                placeholder="Năm"
                style={{ ...inputStyle(isEditing), textAlign: "center" }}
                value={userInfo.birthYear || ""}
                disabled={!isEditing}
                onChange={(e) =>
                  setUserInfo({ ...userInfo, birthYear: e.target.value })
                }
              />
            </div>
          </div>
        </div>

        <div
          style={{
            marginTop: "30px",
            textAlign: "right",
            borderTop: "1px solid #f5f5f5",
            paddingTop: "20px",
          }}
        >
          {!isEditing ? (
            <button
              onClick={() => setIsEditing(true)}
              style={{
                padding: "10px 25px",
                backgroundColor: "#c90000",
                color: "white",
                border: "none",
                borderRadius: "5px",
                cursor: "pointer",
                fontWeight: "bold",
              }}
            >
              Chỉnh sửa thông tin
            </button>
          ) : (
            <>
              <button
                onClick={() => {
                  setIsEditing(false);
                  setUserInfo(originalUserInfo);
                }}
                style={{
                  padding: "10px 25px",
                  marginRight: "10px",
                  backgroundColor: "#6c757d",
                  color: "white",
                  border: "none",
                  borderRadius: "5px",
                  cursor: "pointer",
                }}
              >
                Hủy
              </button>
              <button
                onClick={handleSaveInfo}
                disabled={isLoading}
                style={{
                  padding: "10px 25px",
                  backgroundColor: "#28a745",
                  color: "white",
                  border: "none",
                  borderRadius: "5px",
                  cursor: "pointer",
                  fontWeight: "bold",
                }}
              >
                {isLoading ? "Đang lưu..." : "Lưu thay đổi"}
              </button>
            </>
          )}
        </div>
      </div>

      {/* KHỐI ĐỔI MẬT KHẨU */}
      <div
        style={{
          border: "1px solid #eee",
          padding: "25px",
          borderRadius: "10px",
          backgroundColor: "#fff",
        }}
      >
        <h4
          style={{
            display: "flex",
            alignItems: "center",
            gap: "10px",
            color: "#333",
            marginBottom: "20px",
          }}
        >
          <FaLock color="#c90000" /> Bảo mật & Mật khẩu
        </h4>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr 1fr",
            gap: "15px",
          }}
        >
          <input
            type="password"
            style={inputStyle(true)}
            placeholder="Mật khẩu hiện tại"
            value={password.current}
            onChange={(e) =>
              setPassword({ ...password, current: e.target.value })
            }
          />
          <input
            type="password"
            style={inputStyle(true)}
            placeholder="Mật khẩu mới"
            value={password.new}
            onChange={(e) => setPassword({ ...password, new: e.target.value })}
          />
          <input
            type="password"
            style={inputStyle(true)}
            placeholder="Xác nhận mật khẩu mới"
            value={password.confirm}
            onChange={(e) =>
              setPassword({ ...password, confirm: e.target.value })
            }
          />
        </div>
        <div style={{ marginTop: "20px", textAlign: "right" }}>
          <button
            style={{
              padding: "10px 20px",
              backgroundColor: "#333",
              color: "white",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer",
            }}
          >
            Đổi mật khẩu
          </button>
        </div>
      </div>
    </div>
  );
};

export default PersonalInfo;
